mapper.select:
SELECT PP.PointId, PP.ChnlCode, PP.ProdCode, PP.Remark, PP.State,
       PP.RegistDate, PP.RegistId, PP.RegistName, PP.ChangeDate, PP.ChangeId, PP.ChangeName,
       PH.ProdName, PH.SalePrice, PH.SaleYn, PH.ImgUrl80
FROM shopion.tStrPointProd PP
INNER JOIN shopion.tPrdProd PH ON PP.ProdCode = PH.ProdCode


        AND PP.PointId = #{pPointId}


        AND PP.ChnlCode = #{pChnlCode}


        AND PH.SaleYn = #{pSaleYn}


ORDER BY PP.ProdCode

mapper.insert:
INSERT INTO shopion.tStrPointProd (
    PointId, ChnlCode, ProdCode, Remark, State,
    RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName
) VALUES (
    #{pointId}, #{chnlCode}, #{prodCode}, #{remark}, #{state},
    #{registDate}, #{registId}, #{registName}, #{changeDate}, #{changeId}, #{changeName}
)

mapper.delete:
DELETE FROM shopion.tStrPointProd
WHERE PointId = #{pPointId}

    AND ChnlCode = #{pChnlCode}


    AND ProdCode IN

        #{item}
